seo_schema:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How do I apply for Naimish Nagar now?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Registration for the 1,673 Phase 1 plots is open from 24 September to 24 October 2026 on registration.ldalucknow.in. Buy the ₹1,100 booklet and deposit 5% of the plot price (2.5% for reserved categories). If you want to buy private land around the scheme area, get it verified first."
      }
    },
    {
      "@type": "Question",
      "name": "What is the plot price in Naimish Nagar?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "LDA has fixed the Naimish Nagar rate at ₹3,800 per sq ft. For example, a 112.5 sq m plot (about 1,211 sq ft) will cost about ₹46 lakh. Corner, park-facing and freehold (12%) charges are extra."
      }
    },
    {
      "@type": "Question",
      "name": "When was Naimish Nagar Yojana launched?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The scheme launched on 24 September 2026, together with Varun Vihar Yojana. In February 2026 the plan was ground-breaking in April and registration from May, but the launch was delayed several times."
      }
    },
    {
      "@type": "Question",
      "name": "What is the last date for registration?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The last date is 24 October 2026. LDA will announce the allotment date later."
      }
    },
    {
      "@type": "Question",
      "name": "Is this a land pooling scheme?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. LDA is buying land directly from farmers by consent, through sale deeds (bainama). IT City and Wellness City use land pooling; Naimish Nagar does not."
      }
    },
    {
      "@type": "Question",
      "name": "What precautions should I take before buying?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Always check the khatauni, check for encumbrances and take a lawyer's advice. LDA is buying land in the scheme area, so be careful with private deals there."
      }
    },
    {
      "@type": "Question",
      "name": "How many villages are included?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "18 villages in total. The original 14 are Bhauli, Lakshmipur, Purab Gaon, Purwa, Sairpur, Farrukhabad, Kodri Bhauli, Kamalabad, Kamalapur, Palhari, Gopramau, Barumau, Dhatingra and Saidapur. Paschim Gaon, Dhobaila, Umarbhari and Duggaur were added in August 2025 for roads."
      }
    }
  ]
}
